await test.step('AT-E04 then: 手掛かり欠落の証人経路を示し、人物の認識と真実を区別し続編謎を別集計する', async () => {
  const download = page.waitForEvent('download'); await page.getByRole('button', { name: '検査結果を保存', exact: true }).click();
  analysis = JSON.parse(await readFile((await (await download).path())!, 'utf8'));
  const missing = analysis.findings.find(finding => finding.targetId === question.id && finding.code === 'REQUIRED_INFO_MISSING');
  expect(missing).toBeDefined(); expect(missing!.path).toEqual(expect.arrayContaining([entry.id, reveal.id]));
  expect(analysis.findings.some(finding => finding.targetId === sequel.id && finding.status === 'intentional')).toBe(true);
  expect(analysis.findings.some(finding => finding.targetId === sequel.id && finding.code === 'REQUIRED_INFO_MISSING' && finding.status !== 'intentional')).toBe(false);
});

