  await switchWork(page, world.name); await openEntity(page, 'place', place.name);
  await editData(page, { ...place.data, body: revisedBody });
  await worlds(page); await page.getByLabel('新しい共通世界版の名称', { exact: true }).fill('通常画面で改訂した新世界版');
  await page.getByRole('button', { name: 'この内容を確定版として保存', exact: true }).click();
  await expect(page.getByLabel('新しい共通世界版の名称', { exact: true })).toHaveValue('');
  const revisedWorld = await backup(page);
  const capturedPin = revisedWorld.project.snapshots.find(pin => pin.versionLabel === '通常画面で改訂した新世界版');
  if (!capturedPin) throw new Error('通常画面で保存した新世界版がありません');
  newWorldPin = capturedPin;
  expect(newWorldPin.content.entities.find(entity => entity.id === place.id)).toMatchObject({ kind: 'place', name: place.name, data: { body: revisedBody } });
  expect(revisedWorld.project.snapshots.find(pin => pin.id === worldPin.id)).toEqual(worldPin);
  await switchWork(page, p.name); await worlds(page);
  await page.getByLabel('参照する共通世界', { exact: true }).selectOption(world.projectId);
  const selectedPin = await page.getByLabel('固定する共通世界版', { exact: true }).locator('option').filter({ hasText: newWorldPin.versionLabel }).getAttribute('value');
  expect(selectedPin).toBe(newWorldPin.id);
  await page.getByLabel('固定する共通世界版', { exact: true }).selectOption(newWorldPin.id);
  await expect(page.getByRole('checkbox', { name: place.name, exact: true })).toBeChecked();
  const beforePreview = await authorFingerprint(page);
  await page.getByRole('button', { name: '適用前の差分・影響を確認', exact: true }).click();
  const impact = page.getByRole('dialog', { name: '共通世界版の変更前の影響', exact: true });
  await expect(impact.getByRole('heading', { name: '共通世界版の変更前の影響', level: 2, exact: true })).toBeVisible();
  const impactTitleId = await impact.getAttribute('aria-labelledby');
  expect(impactTitleId).toBeTruthy();
  await expect(impact).toContainText(`現在版から ${newWorldPin.versionLabel} へ固定先を変更します。採用設定 1件。内容のhashを確認済みです。`);
  const changedPlace = impact.locator('.world-version-change').filter({ has: page.locator('code').filter({ hasText: place.id }) });
  await expect(changedPlace).toHaveCount(1);
  await expect(changedPlace.locator('strong')).toHaveText(`変更 · ${place.name}`);
  await expect(changedPlace.locator('code')).toHaveText(place.id);
  for (const affected of [event, novel]) await expect(impact.getByRole('button', { name: `${affected.name} · ${affected.id.slice(-6)}`, exact: true })).toBeVisible();
  expect(await authorFingerprint(page)).toBe(beforePreview);
  const impactText = await impact.innerText();
  await changedPlace.getByRole('button', { name: '元情報を確認', exact: true }).click();
  const fixedPreview = page.getByRole('dialog', { name: '固定版の参照先', exact: true });
  await expect(fixedPreview).toBeVisible();
  await expect(fixedPreview.getByRole('heading', { name: '固定版の参照先', level: 2, exact: true })).toBeVisible();
  const fixedTitleId = await fixedPreview.getAttribute('aria-labelledby');
  expect(fixedTitleId).toBeTruthy();
  expect(fixedTitleId).not.toBe(impactTitleId);
  await expect(fixedPreview.getByRole('heading', { name: '固定版の参照先', level: 2, exact: true })).toHaveAttribute('id', fixedTitleId!);
  await expect(fixedPreview.getByRole('heading', { name: place.name, level: 2, exact: true })).toBeVisible();
  await expect(fixedPreview).toContainText(`固定版: ${newWorldPin.versionLabel} · 保存日時: ${newWorldPin.createdAt}`);
  await expect(fixedPreview).toContainText(revisedBody[0].text);
  await expect(fixedPreview).toContainText('世界作品の現在の編集とは区別して表示しています。');
  expect(await authorFingerprint(page)).toBe(beforePreview);
  const fixedPreviewText = await fixedPreview.innerText();
  await fixedPreview.getByRole('button', { name: '閉じる', exact: true }).click();
  await expect(fixedPreview).toHaveCount(0);
  await expect(impact.getByRole('heading', { name: '共通世界版の変更前の影響', level: 2, exact: true })).toBeVisible();
  expect(await authorFingerprint(page)).toBe(beforePreview);
  await attachObservation(info, 'AT-E09-world-revision-preview', { changedPlaceId: place.id, newWorldPin: { id: newWorldPin.id, contentHash: newWorldPin.contentHash, versionLabel: newWorldPin.versionLabel, createdAt: newWorldPin.createdAt }, affectedIds: [event.id, novel.id], impactText, fixedPreviewText });
  await expect(impact.getByRole('button', { name: '確認した固定版・採用設定を保存', exact: true })).toBeEnabled();
  await impact.getByRole('button', { name: '確認した固定版・採用設定を保存', exact: true }).click();
  await expect(impact).toHaveCount(0);
  await openEntity(page, 'event', event.name); await editData(page, { ...event.data, time: { mode: 'instant', at: '15', calendarId: p.calendarId } });
  await navigate(page, /^構成/); await page.getByRole('tab', { name: '試読・検査', exact: true }).click();
  for (const [entry, edge] of [[a, ea], [b, eb]]) {
    await page.getByLabel('試読する作品版', { exact: true }).selectOption(''); await page.getByLabel('試読の開始点', { exact: true }).selectOption(entry.id);
    await page.getByRole('button', { name: /^(試読を始める|この状態から開始し直す)$/ }).click();
    await page.getByRole('button', { name: edge.name, exact: true }).click(); await page.getByRole('button', { name: '経路を記録', exact: true }).click();
    await expect(page.getByRole('status').filter({ hasText: '開始状態と経路を端末内に保存しました' })).toBeVisible();
  }
  await production(page);
  await expect(page.locator('.production-planning')).toContainText('固有場面 1');
  const route = page.getByLabel('制作量を比較する経路', { exact: true });
  const ids = await route.locator('option').evaluateAll(options => options.map(option => (option as HTMLOptionElement).value).filter(Boolean)); expect(ids).toHaveLength(2);
  for (const id of ids) { await route.selectOption(id); await expect(page.locator('.production-planning')).toContainText('選択経路の提示量 1'); }
});

