sources.source_excerpt:
await test.step('AT-E09 then: 固有制作数は一回、体験量は各経路で算出し、小説旧版と実期限は不変', async () => {
  const saved = await backup(page);
  expect(saved.project.entities.filter(entity => entity.kind === 'scene')).toHaveLength(1);
  expect(saved.project.entities.find(entity => entity.id === novel.id)).toMatchObject({ data: { body: novel.data.body, baseSnapshotId: oldEdition.id, releaseAt: novel.data.releaseAt } });
  expect(saved.project.snapshots.find(pin => pin.id === oldEdition.id)).toEqual(oldEdition);
  for (const id of [written.id, implementation.id]) expect(saved.project.entities.find(entity => entity.id === id)).toMatchObject({ data: { deadline } });
  expect(saved.project.worldReferences.find(reference => reference.projectId === world.projectId)).toEqual({ projectId: world.projectId, immutableSnapshotId: newWorldPin.id, contentHash: newWorldPin.contentHash });
  expect(saved.project.views.find(view => view.view === `world-adoption:${world.projectId}`)?.entityIds).toEqual([place.id]);
  const savedNewPin = saved.worlds[newWorldPin.id]?.snapshots.find(pin => pin.id === newWorldPin.id);
  expect(savedNewPin).toEqual(newWorldPin);
  expect(savedNewPin?.content.entities.find(entity => entity.id === place.id)).toMatchObject({ kind: 'place', name: place.name, data: { body: revisedBody } });
  expect(saved.worlds[worldPin.id]?.snapshots.find(pin => pin.id === worldPin.id)).toEqual(worldPin);
});

