await test.step('AT-E10 when: 同じ記録を再実行して探索上限まで解析する', async () => {
  await page.getByRole('button', { name: '真の選択肢から抽選', exact: true }).click();
  randomHeading = await page.locator('.reader-sheet h2').innerText(); randomState = await page.locator('.reader-state-counts').innerText();
  await page.getByRole('button', { name: '経路を記録', exact: true }).click(); await expect(page.getByRole('status').filter({ hasText: '開始状態と経路を端末内に保存しました' })).toBeVisible();
  await page.locator('.saved-traces').getByRole('button', { name: /再実行して状態を比較/ }).first().click();
  await expect(page.locator('.reader-sheet h2')).toHaveText(randomHeading); expect(await page.locator('.reader-state-counts').innerText()).toBe(randomState);
  await page.getByLabel('試読する作品版', { exact: true }).selectOption(''); await page.getByLabel('試読の開始点', { exact: true }).selectOption(entry.id);
  await page.getByRole('button', { name: '到達性と行き止まりを検査', exact: true }).click();
  await expect(page.locator('.analysis-result-heading')).toBeVisible({ timeout: 35_000 });
  const pending = page.waitForEvent('download'); await page.getByRole('button', { name: '検査結果を保存', exact: true }).click(); analysis = JSON.parse(await readFile((await (await pending).path())!, 'utf8'));
});

